import{_ as h,o as t,c as a,a2 as c}from"./chunks/framework.BBd5PKnH.js";const p=JSON.parse('{"title":"Chọn Cache Pattern Phù Hợp Với App ?","description":"Chắc hẳn ai làm backend cũng từng gặp cảnh hệ thống đang chạy ngon lành, tự dưng traffic tăng một chút là database bắt đầu \\"thở oxy\\". Nhiều trường hợp, vấn đề không nằm ở DB hay server mà đơn giản là chưa tận dụng cache đúng cách. ","frontmatter":{"title":"Chọn Cache Pattern Phù Hợp Với App ?","description":"Chắc hẳn ai làm backend cũng từng gặp cảnh hệ thống đang chạy ngon lành, tự dưng traffic tăng một chút là database bắt đầu \\"thở oxy\\". Nhiều trường hợp, vấn đề không nằm ở DB hay server mà đơn giản là chưa tận dụng cache đúng cách. ","date":"2026-06-03T00:00:00.000Z"},"headers":[],"relativePath":"notes/chon-cache-pattern-phu-hop-voi-app.md","filePath":"notes/chon-cache-pattern-phu-hop-voi-app.md"}'),i={name:"notes/chon-cache-pattern-phu-hop-voi-app.md"};function e(l,n,o,u,g,r){return t(),a("div",null,[...n[0]||(n[0]=[c('<p>Chắc hẳn ai làm backend cũng từng gặp cảnh hệ thống đang chạy ngon lành, tự dưng traffic tăng một chút là DB bắt đầu &quot;thở oxy&quot;. Nhiều trường hợp, vấn đề không nằm ở DB hay server mà đơn giản là chưa tận dụng cache đúng cách.</p><p>Nhưng cache không phải cứ thêm Redis vào là xong. Mỗi cách sử dụng cache sẽ phù hợp với một bài toán khác nhau. Chọn đúng thì hệ thống nhanh và ổn định hơn rất nhiều. Chọn sai thì lại phải đau đầu xử lý stale data, cache miss hàng loạt hoặc thậm chí mất dữ liệu.</p><p>Trong bài viết này, mình sẽ đi qua 4 cache pattern phổ biến nhất và những trường hợp thực tế mà chúng thường được sử dụng.</p><h2 id="_1-cache-aside" tabindex="-1">1. Cache Aside <a class="header-anchor" href="#_1-cache-aside" aria-label="Permalink to &quot;1. Cache Aside&quot;">​</a></h2><blockquote><p>⚠️ Ảnh thiếu: <strong>cache aside.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Đây có lẽ là pattern quen thuộc nhất với đa số developer.</p><p>Luồng hoạt động khá đơn giản:</p><ol><li>App check trong cache trước.</li><li>Nếu cache có dữ liệu (cache hit) thì trả về ngay.</li><li>Nếu cache không có (cache miss) thì đọc từ DB.</li><li>Sau khi lấy được dữ liệu từ DB, ứng dụng lưu lại vào cache để dùng cho những lần sau.</li></ol><p>Nói cách khác, backend chịu trách nhiệm hoàn toàn cho việc đọc và ghi cache.</p><h3 id="vi-du-thuc-te" tabindex="-1">Ví dụ thực tế <a class="header-anchor" href="#vi-du-thuc-te" aria-label="Permalink to &quot;Ví dụ thực tế&quot;">​</a></h3><p>Một ví dụ điển hình là trang hồ sơ người dùng trên mạng xã hội.</p><p>Thông tin như tên, avatar hay bio thường không thay đổi nhiều nhưng lại được đọc liên tục. Vì vậy mỗi lần có người truy cập profile, hệ thống sẽ kiểm tra Redis trước. Nếu không có mới query xuống DB rồi cache lại kết quả.</p><h3 id="khi-nao-nen-dung" tabindex="-1">Khi nào nên dùng? <a class="header-anchor" href="#khi-nao-nen-dung" aria-label="Permalink to &quot;Khi nào nên dùng?&quot;">​</a></h3><ul><li>Dữ liệu được đọc nhiều hơn ghi.</li><li>Muốn toàn quyền kiểm soát logic cache.</li><li>Cache và dữ liệu trong DB không nhất thiết phải có cùng cấu trúc.</li><li>Muốn hệ thống vẫn hoạt động nếu cache gặp sự cố.</li></ul><h3 id="điem-can-luu-y" tabindex="-1">Điểm cần lưu ý <a class="header-anchor" href="#điem-can-luu-y" aria-label="Permalink to &quot;Điểm cần lưu ý&quot;">​</a></h3><p>Vấn đề thường gặp nhất là dữ liệu bị cũ (stale data). Nếu dữ liệu trong DB đã thay đổi nhưng cache chưa được cập nhật, người dùng sẽ tiếp tục nhìn thấy data cũ. Vì vậy Cache Aside thường đi kèm với TTL hoặc cơ chế invalidate cache khi có thao tác ghi. Với ví dụ trên, chẳng hạn user update lại thông tin cá nhân vào DB, nhưng cache vẫn chưa cập nhật thì load trên UI vẫn là thông tin cũ.</p><h2 id="_2-read-through" tabindex="-1">2. Read Through <a class="header-anchor" href="#_2-read-through" aria-label="Permalink to &quot;2. Read Through&quot;">​</a></h2><p>Read Through có cách hoạt động khá giống Cache Aside nhưng trách nhiệm được chuyển sang cache layer. Thay vì app tự query từ DB khi cache miss thì cache sẽ đi query, app chỉ giao tiếp với cache.</p><blockquote><p>⚠️ Ảnh thiếu: <strong>read through.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Luồng xử lý sẽ là:</p><ol><li>App yêu cầu dữ liệu từ cache.</li><li>Cache hit → trả về ngay.</li><li>Cache miss → cache query DB, lưu lại rồi trả kết quả cho app.</li></ol><p>Từ góc nhìn của ứng dụng, DB gần như bị &quot;ẩn đi&quot;.</p><h3 id="vi-du-thuc-te-1" tabindex="-1">Ví dụ thực tế <a class="header-anchor" href="#vi-du-thuc-te-1" aria-label="Permalink to &quot;Ví dụ thực tế&quot;">​</a></h3><p>Các hệ thống đọc nội dung như blog, tin tức hoặc tài liệu thường rất phù hợp với mô hình này. Nhiều framework hiện nay như Spring Cache hay Django Cache Framework hỗ trợ khá tốt. Developer chỉ cần đánh dấu hàm cần cache, phần còn lại framework sẽ xử lý.</p><h3 id="khi-nao-nen-dung-1" tabindex="-1">Khi nào nên dùng? <a class="header-anchor" href="#khi-nao-nen-dung-1" aria-label="Permalink to &quot;Khi nào nên dùng?&quot;">​</a></h3><ul><li>Hệ thống thiên về đọc dữ liệu.</li><li>Muốn giảm lượng code liên quan đến cache.</li><li>Muốn chuẩn hóa cách cache trong toàn bộ ứng dụng.</li></ul><h3 id="điem-can-luu-y-1" tabindex="-1">Điểm cần lưu ý <a class="header-anchor" href="#điem-can-luu-y-1" aria-label="Permalink to &quot;Điểm cần lưu ý&quot;">​</a></h3><p>Lần truy cập đầu tiên chắc chắn sẽ bị cache miss. Ngoài ra, Read Through thường hoạt động tốt nhất khi dữ liệu trong cache và dữ liệu trong DB có cùng cấu trúc. Nếu cần transform dữ liệu phức tạp trước khi cache thì Cache Aside sẽ linh hoạt hơn.</p><h2 id="_3-write-back-write-behind-–-ghi-truoc-đong-bo-sau" tabindex="-1">3. Write Back (Write Behind) – Ghi trước, đồng bộ sau <a class="header-anchor" href="#_3-write-back-write-behind-–-ghi-truoc-đong-bo-sau" aria-label="Permalink to &quot;3. Write Back (Write Behind) – Ghi trước, đồng bộ sau&quot;">​</a></h2><p>Nếu Cache Aside và Read Through chủ yếu tối ưu cho việc đọc thì Write Back lại tập trung vào tốc độ ghi.</p><blockquote><p>⚠️ Ảnh thiếu: <strong>write back.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Thay vì ghi xuống DB ngay lập tức, hệ thống:</p><ol><li>Ghi vào cache trước.</li><li>Trả kết quả thành công cho người dùng.</li><li>Đồng bộ dữ liệu từ cache xuống DB theo lô hoặc theo lịch định kỳ.</li></ol><p>Nhờ vậy độ trễ khi ghi giảm đáng kể.</p><h3 id="vi-du-thuc-te-2" tabindex="-1">Ví dụ thực tế <a class="header-anchor" href="#vi-du-thuc-te-2" aria-label="Permalink to &quot;Ví dụ thực tế&quot;">​</a></h3><p>Like, view hoặc reaction trên mạng xã hội là ví dụ kinh điển. Nếu mỗi lượt xem video đều ghi trực tiếp vào database thì hệ thống sẽ nhanh chóng trở thành một vấn đề nếu có ông nào spam click. Cáchcách phổ biến là:</p><ul><li>Tăng counter trong Redis.</li><li>Định kỳ vài giây hoặc vài nghìn lượt cập nhật thì ghi xuống database.</li></ul><p>Game leaderboard thời gian thực cũng thường áp dụng cách tiếp cận tương tự.</p><h3 id="khi-nao-nen-dung-2" tabindex="-1">Khi nào nên dùng? <a class="header-anchor" href="#khi-nao-nen-dung-2" aria-label="Permalink to &quot;Khi nào nên dùng?&quot;">​</a></h3><ul><li>Hệ thống có lượng ghi rất lớn.</li><li>Cần giảm áp lực cho database.</li><li>Chấp nhận eventual consistency.</li></ul><h3 id="điem-can-luu-y-2" tabindex="-1">Điểm cần lưu ý <a class="header-anchor" href="#điem-can-luu-y-2" aria-label="Permalink to &quot;Điểm cần lưu ý&quot;">​</a></h3><p>Trade-off lớn nhất là nguy cơ mất dữ liệu.</p><p>Nếu cache gặp sự cố trước khi dữ liệu được đồng bộ xuống DB, phần dữ liệu đó có thể biến mất hoàn toàn. Vì vậy Write Back thường cần kết hợp với persistence hoặc replication để giảm rủi ro.</p><h2 id="_4-write-around-–-ghi-thang-vao-db-cache-khi-thuc-su-can" tabindex="-1">4. Write Around – Ghi thẳng vào DB, cache khi thực sự cần <a class="header-anchor" href="#_4-write-around-–-ghi-thang-vao-db-cache-khi-thuc-su-can" aria-label="Permalink to &quot;4. Write Around – Ghi thẳng vào DB, cache khi thực sự cần&quot;">​</a></h2><blockquote><p>⚠️ Ảnh thiếu: <strong>write around.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Write Around có triết lý khá đơn giản:</p><ul><li>Ghi trực tiếp vào database.</li><li>Không đưa dữ liệu mới vào cache ngay.</li><li>Chỉ cache khi có nhu cầu đọc thực sự.</li></ul><p>Mục tiêu là tránh làm đầy cache bằng những dữ liệu có thể chẳng bao giờ được truy cập lại.</p><h3 id="vi-du-thuc-te-3" tabindex="-1">Ví dụ thực tế <a class="header-anchor" href="#vi-du-thuc-te-3" aria-label="Permalink to &quot;Ví dụ thực tế&quot;">​</a></h3><p>Log hệ thống là trường hợp rất điển hình. Hàng triệu bản ghi log có thể được tạo ra mỗi ngày, nhưng phần lớn sẽ không bao giờ được đọc lại. Nếu mỗi lần ghi log đều cache luôn thì chỉ đang lãng phí tài nguyên bộ nhớ.</p><h3 id="khi-nao-nen-dung-3" tabindex="-1">Khi nào nên dùng? <a class="header-anchor" href="#khi-nao-nen-dung-3" aria-label="Permalink to &quot;Khi nào nên dùng?&quot;">​</a></h3><ul><li>Dữ liệu được ghi nhiều nhưng ít khi đọc lại ngay.</li><li>Muốn hạn chế cache pollution.</li><li>Muốn tối ưu dung lượng cache cho những dữ liệu thực sự quan trọng.</li></ul><h3 id="điem-can-luu-y-3" tabindex="-1">Điểm cần lưu ý <a class="header-anchor" href="#điem-can-luu-y-3" aria-label="Permalink to &quot;Điểm cần lưu ý&quot;">​</a></h3><p>Lần đọc đầu tiên thường chậm hơn vì phải truy vấn database.</p><p>Nếu cơ chế invalidate không tốt, hệ thống vẫn có thể gặp vấn đề stale data giống các pattern khác.</p><h2 id="so-sanh-nhanh" tabindex="-1">So sánh nhanh <a class="header-anchor" href="#so-sanh-nhanh" aria-label="Permalink to &quot;So sánh nhanh&quot;">​</a></h2><blockquote><p>⚠️ Ảnh thiếu: <strong>Screenshot 2026-06-03 at 17.08.06.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Không có cache pattern nào là &quot;tốt nhất&quot; cho mọi trường hợp.</p><p>Điều quan trọng là hiểu đặc điểm dữ liệu của hệ thống:</p><ul><li>Đọc nhiều hay ghi nhiều?</li><li>Chấp nhận dữ liệu cũ trong bao lâu?</li><li>Cache gặp sự cố thì điều gì sẽ xảy ra?</li><li>Dữ liệu vừa ghi có cần được đọc lại ngay không?</li></ul><p>Khi trả lời được những câu hỏi đó, việc chọn cache pattern sẽ trở nên dễ dàng hơn rất nhiều. Và trong đa số dự án thực tế, bài toán không phải là &quot;có dùng cache hay không&quot;, mà là &quot;dùng cache theo cách nào cho hợp lý&quot;.</p>',62)])])}const s=h(i,[["render",e]]);export{p as __pageData,s as default};
